    }
}
//==========================VOUCHER=====================//
let createNewVoucher = async (req, res) => {
    try {
        let data = await voucherService.createNewVoucher(req.body);
        return res.status(200).json(data);
    } catch (error) {
        console.log(error)
        return res.status(200).json({
            errCode: -1,
