        (await commerce.activeSessions(tx)).some(session => session.checkout.lines.some(line => Number(line.productId) === Number(id)))) {
        fail('Không thể xóa biến thể đã có giỏ hàng, phiếu nhập, đơn hàng hoặc lịch sử kiểm kê. Hãy ngừng kinh doanh sản phẩm thay vì xóa.', 2);
    }
}
