"use strict";

const {
  Op,
  Transaction
} = require('sequelize');
const {
  fail,
  positiveInteger,
  money,
  normalizeLines,
  voucherDiscount,
  voucherIsActive
} = require('../utils/commerce');
const {
  recordOrderEvent
} = require('./orderEventService');

// Inventory is receipts minus non-cancelled orders and unexpired payment reservations.
function createCommerceService(db) {
  const transaction = work => db.sequelize.transaction({
    isolationLevel: Transaction.ISOLATION_LEVELS.READ_COMMITTED
  }, work);
  const options = tx => tx ? {
    transaction: tx
  } : {};
  const lockOptions = tx => tx ? {
    transaction: tx,
    lock: tx.LOCK.UPDATE
  } : {};
  async function activeSessions(tx, excludeSessionId) {
    const rows = await db.PaymentSession.findAll({
      where: {
        status: 'PENDING',
        expiresAt: {
          [Op.gt]: new Date()
        }
      },
      ...options(tx),
      raw: true
    });
    return rows.filter(row => row.id !== excludeSessionId).map(row => ({
      ...row,
      checkout: JSON.parse(row.checkoutData)
    }));
  }
  async function stockSnapshot(productId, tx, excludeSessionId) {
    const received = Number(await db.ReceiptDetail.sum('quantity', {
      where: {
        productDetailSizeId: productId
      },
      ...options(tx)
    })) || 0;
    const lines = await db.OrderDetail.findAll({
      where: {
        productId
      },
      ...options(tx),
      raw: true
    });
    const orderIds = [...new Set(lines.map(line => line.orderId))];
    const orders = orderIds.length ? await db.OrderProduct.findAll({
      where: {
        id: {
          [Op.in]: orderIds
        },
        statusId: {
          [Op.ne]: 'S7'
        }
      },
      attributes: ['id'],
      ...options(tx),
      raw: true
    }) : [];
