    const adjusted = db.StockMovement ? Number(await db.StockMovement.sum('quantity', {
      where: {
        productDetailSizeId: productId
      },
      ...options(tx)
    })) || 0 : 0;
    const onHand = received + returned + adjusted - sold;
    return {
      onHand,
      reserved,
      available: Math.max(0, onHand - reserved)
