      raw: true
    });
    if (!address) fail('Địa chỉ giao hàng không thuộc tài khoản của bạn.', 403);
    const shipping = await db.TypeShip.findOne({
      where: {
        id: data.typeShipId
      },
      ...options(tx),
      raw: true
    });
    if (!shipping) fail('Phương thức vận chuyển không tồn tại.', 2);
    let subtotal = 0;
    for (const line of lines) {
      const variant = await db.ProductDetailSize.findOne({
        where: {
          id: line.productId
        },
        ...options(tx),
        raw: true
      });
      const detail = await db.ProductDetail.findOne({
        where: {
          id: variant.productdetailId
        },
        ...options(tx),
        raw: true
      });
      const product = detail && (await db.Product.findOne({
        where: {
          id: detail.productId,
          statusId: 'S1'
        },
        ...options(tx),
        raw: true
      }));
      if (!product) fail('Sản phẩm đã ngừng kinh doanh.', 2);
