    await db.OrderDetail.bulkCreate(lines.map(({
      productId,
      quantity,
      realPrice
    }) => ({
      orderId: order.id,
      productId,
      quantity,
      realPrice
    })), options(tx));
    // Remove only purchased quantities, retaining unrelated or newly added items.
    for (const line of lines) {
      const cartRows = await db.ShopCart.findAll({
