      where: {
        userId,
        voucherId: checkout.voucherId,
        status: 0
      },
      ...options(tx)
    });
    await recordOrderEvent(db, {
      order,
      type: 'ORDER_CREATED',
      title: 'Đặt hàng thành công',
      message: `Đơn #${order.id} đã được tạo${paid ? ' và thanh toán trực tuyến được xác nhận' : ', thanh toán khi nhận hàng'}.`,
      actorId: userId,
      metadata: {
        paid,
        totalPrice: checkout.totalPrice
      }
    }, tx);
    return {
      errCode: 0,
      errMessage: 'Đặt hàng thành công.',
