  if (!user) return denied();
  const id = admin(user) && userId ? userId : user.id;
  return decorateRooms(await db.RoomMessage.findAll({ where: { [Op.or]: [{ userOne: id }, { userTwo: id }] }, order: [['updatedAt', 'DESC']], raw: true }));
