const getCountCardStatistic = () => resultOf(async () => {
    const [countUser, countProduct, countReview, countOrder] = await Promise.all([
        db.User.count({ where: { statusId: 'S1' } }), db.Product.count(), db.Comment.count({ where: { star: { [Op.gt]: 0 } } }),
