          id: {
            [Op.in]: literal(`(SELECT MIN(\`firstDetail\`.\`id\`) FROM \`Productdetails\` AS \`firstDetail\` WHERE \`firstDetail\`.\`productId\` IN (${productIds.join(',')}) GROUP BY \`firstDetail\`.\`productId\`)`)
          }
        })
      },
      attributes: detailAttributes,
      order: [['id', 'ASC']],
      raw: true
    });
