      attributes: cardAttributes,
      include: associations(),
      order,
      raw: true,
      nest: true
    };
  }
  async function list(data = {}, {
    admin = false
  } = {}) {
    const where = admin ? {} : {
      statusId: 'S1'
    };
    if (data.categoryId && data.categoryId !== 'ALL') where.categoryId = data.categoryId;
    if (data.brandId && data.brandId !== 'ALL') where.brandId = data.brandId;
    if (typeof data.keyword === 'string' && data.keyword.trim()) where.name = {
      [Op.substring]: data.keyword.trim()
