    const query = productQuery(where, order);
    // Empty limit is used by the existing admin receipt selector to load its full option list.
    if (!admin || Number(data.limit) > 0) Object.assign(query, {
      limit: listLimit(data.limit),
      offset: listOffset(data.offset)
    });
    if (admin) query.attributes = [...cardAttributes, 'madeby', 'material'];
    const result = await db.Product.findAndCountAll(query);
    return {
      errCode: 0,
      count: result.count,
      data: await hydrate(result.rows, {
        admin
      })
    };
  }
  async function featured(limit) {
    const products = await db.Product.findAll({
      ...productQuery({
        statusId: 'S1'
      }, [['view', 'DESC'], ['id', 'DESC']]),
      limit: listLimit(limit)
    });
    return {
      errCode: 0,
      data: await hydrate(products)
    };
  }
  async function newest(limit) {
    const products = await db.Product.findAll({
      ...productQuery({
        statusId: 'S1'
      }, [['createdAt', 'DESC'], ['id', 'DESC']]),
      limit: listLimit(limit)
    });
    return {
      errCode: 0,
      data: await hydrate(products)
