    if (!safeIds.length) return [];
    const order = literal(`CASE \`Product\`.\`id\` ${safeIds.map((id, index) => `WHEN ${id} THEN ${index}`).join(' ')} END`);
    const products = await db.Product.findAll({
      ...productQuery({
        id: {
          [Op.in]: safeIds
        },
        statusId: 'S1'
      }, [[order, 'ASC'], ['id', 'ASC']]),
      limit: listLimit(limit)
    });
    return hydrate(products);
  }
  async function cart(data = {}) {
    if (!data.userId) return {
      errCode: 1,
      errMessage: 'Missing required parameter!'
    };
    const carts = await db.ShopCart.findAll({
      where: {
        userId: data.userId
      },
      attributes: ['productdetailsizeId'],
      raw: true
    });
    if (!carts.length) return {
      errCode: 0,
      data: []
    };
    const variantIds = [...new Set(carts.map(row => Number(row.productdetailsizeId)))];
    const variants = await db.ProductDetailSize.findAll({
      where: {
        id: {
          [Op.in]: variantIds
        }
      },
      attributes: ['productdetailId'],
      raw: true
    });
    const details = variants.length ? await db.ProductDetail.findAll({
      where: {
        id: {
          [Op.in]: [...new Set(variants.map(row => Number(row.productdetailId)))]
        }
      },
      attributes: ['productId'],
      raw: true
    }) : [];
    return {
      errCode: 0,
      data: await byRankedIds(details.map(row => row.productId), data.limit)
    };
  }
  async function recommend(data = {}) {
    if (!data.userId) return {
      errCode: 1,
      errMessage: 'Missing required parameter!'
    };
    // A bounded sparse score avoids fitting a dense user × product matrix on each page request.
    const ratings = await db.Comment.findAll({
      where: {
        productId: {
          [Op.not]: null
        },
        star: {
          [Op.between]: [1, 5]
        }
      },
      attributes: ['productId', 'userId', 'star'],
      order: [['id', 'DESC']],
      limit: 2000,
      raw: true
    });
