        ...locked(tx),
        raw: false
      });
      if (!order) fail('Không tìm thấy đơn hàng.', 2);
      if (!internalDelivery(order)) fail('Đơn đã giao cho hãng vận chuyển ngoài, không thể nhận giao nội bộ.', 2);
      // A retry by the assigned courier has no additional effect.
