  });
  const updateStatusOrder = (data, actor) => resultOf(async () => {
    if (!validId(data.id) || !['S4', 'S5', 'S6', 'S7'].includes(data.statusId)) fail('Mã đơn hàng hoặc trạng thái không hợp lệ.');
