      if (order.statusId === 'S8') return orderResult(order, 'Lần giao thất bại này đã được ghi nhận.');
      if (order.statusId !== 'S5') fail('Chỉ đơn đang giao mới được ghi nhận giao thất bại.', 2);
      order.statusId = 'S8';
      order.deliveryAttempts = (Number(order.deliveryAttempts) || 0) + 1;
      order.failedDeliveryAt = new Date();
      order.lastDeliveryFailureReason = reason;
      await order.save({
        transaction: tx
      });
