    const limit = Number.isInteger(configuredLimit) && configuredLimit > 0 ? configuredLimit : 3;
    if (Number(order.deliveryAttempts) >= limit) fail(`Đã giao thất bại ${limit} lần. Vui lòng hoàn hàng về kho.`, 2);
