        pick_name: config.pickup.name,
        pick_tel: config.pickup.phone,
        pick_address: config.pickup.address,
        pick_province: config.pickup.province,
        pick_district: config.pickup.district,
        pick_ward: config.pickup.ward,
        name: address.shipName,
        tel: address.shipPhonenumber,
        address: address.shipAdress,
        province: destination.province,
        district: destination.district,
        ward: destination.ward,
