        const base = whereFor(filter, 'r.requestedAt'); const selected = `${base.sql}${status === 'ALL' ? '' : ' AND r.status = :status'}`;
        const replacements = { ...base.replacements, status, limit: paging.pageSize, offset: paging.offset };
